// JT-ZERO v35: compare FC ATTITUDE gravity direction with static accelerometer gravity direction.
// Russian GUI, event-driven route 0 -> +90 -> 0 -> -90 -> 0.
#define JTZERO_V10_NO_MAIN
#include "live_mono_imu_integrator_v10.cpp"
#undef JTZERO_V10_NO_MAIN
#include <array>
#include <fstream>
#include <iomanip>

namespace jtzero_v35 {
constexpr const char* kCsv35="/home/vio/jtzero_live_fc_accel_tilt_v35.csv";
constexpr const char* kWindow35="JT-ZERO: FC ПРОТИВ GRAVITY ACCEL v35";
constexpr int kPhases35=5;
constexpr double kTargets35[kPhases35]={0,90,0,-90,0};
constexpr const char* kNames35[kPhases35]={"0_start","+90","0_mid","-90","0_final"};
constexpr double kYawTol35=1.5,kGyroStill35=.035,kAccNormTol35=.45;
constexpr int kStableSamples35=100,kCollectSamples35=500;

struct Att35{bool valid=false;double roll=0,pitch=0,yaw=0;Eigen::Matrix3d R=Eigen::Matrix3d::Identity();};
struct Row35{int phase=0;uint64_t us=0;double rel_yaw=0,fc_roll=0,fc_pitch=0,fc_yaw=0;Eigen::Vector3d acc=Eigen::Vector3d::Zero();};
struct Stats35{int n=0;Eigen::Vector3d sum_acc=Eigen::Vector3d::Zero();double sr=0,sp=0,sy=0;void add(const Row35&r){++n;sum_acc+=r.acc;sr+=r.fc_roll;sp+=r.fc_pitch;sy+=r.rel_yaw;}Eigen::Vector3d meanAcc()const{Eigen::Vector3d o=Eigen::Vector3d::Zero();if(n)o=sum_acc/double(n);return o;}};
static double normDeg35(double x){while(x>180)x-=360;while(x<-180)x+=360;return x;}
static double angleDeg35(const Eigen::Vector3d&a,const Eigen::Vector3d&b){double c=a.normalized().dot(b.normalized());c=std::max(-1.0,std::min(1.0,c));return std::acos(c)*180.0/kPi;}
static Eigen::Vector3d fcGravityBody35(double r,double p,double y){return -jtzero_v10::fcRnedFlu(r,p,y).transpose()*Eigen::Vector3d(0,0,1);}
static void accelTilt35(const Eigen::Vector3d&a,double&roll,double&pitch){Eigen::Vector3d u=a.normalized();roll=std::atan2(u.y(),u.z())*180.0/kPi;pitch=std::atan2(-u.x(),std::sqrt(u.y()*u.y()+u.z()*u.z()))*180.0/kPi;}
static void save35(const std::vector<Row35>&v){std::ofstream f(kCsv35);f<<std::fixed<<std::setprecision(9)<<"phase,phase_name,imu_us,rel_yaw_deg,fc_roll_deg,fc_pitch_deg,fc_yaw_deg,ax,ay,az\n";for(const auto&r:v)f<<r.phase<<','<<kNames35[r.phase]<<','<<r.us<<','<<r.rel_yaw<<','<<r.fc_roll<<','<<r.fc_pitch<<','<<r.fc_yaw<<','<<r.acc.x()<<','<<r.acc.y()<<','<<r.acc.z()<<'\n';}
static void summary35(const std::array<Stats35,kPhases35>&s){
 std::cout<<std::fixed<<std::setprecision(9)<<"\n============================================================\nJT-ZERO FC vs ACCEL GRAVITY v35 RESULT\n============================================================\n";
 double r0=s[0].sr/s[0].n,p0=s[0].sp/s[0].n,y0=s[0].sy/s[0].n,ar0=0,ap0=0;Eigen::Vector3d a0=s[0].meanAcc();accelTilt35(a0,ar0,ap0);
 double worst=0;for(int i=0;i<kPhases35;i++){double r=s[i].sr/s[i].n,p=s[i].sp/s[i].n,y=s[i].sy/s[i].n,ar=0,ap=0;Eigen::Vector3d a=s[i].meanAcc();accelTilt35(a,ar,ap);Eigen::Vector3d gfc=fcGravityBody35(r,p,y),gacc=-a.normalized();double ga=angleDeg35(gfc,gacc);worst=std::max(worst,ga);std::cout<<"\n"<<kNames35[i]<<" target="<<kTargets35[i]<<" n="<<s[i].n<<"\n FC R/P/Yrel=["<<r<<","<<p<<","<<y<<"] deg\n ACC tilt R/P=["<<ar<<","<<ap<<"] deg\n mean accel=["<<a.transpose()<<"] m/s^2 |a|="<<a.norm()<<"\n FC-vs-ACC gravity angle="<<ga<<" deg\n delta FC tilt vs start=["<<r-r0<<","<<p-p0<<"] deg\n delta ACC tilt vs start=["<<ar-ar0<<","<<ap-ap0<<"] deg\n";}
 double rf=s[4].sr/s[4].n,pf=s[4].sp/s[4].n,arf=0,apf=0;accelTilt35(s[4].meanAcc(),arf,apf);double dfc=std::hypot(rf-r0,pf-p0),dacc=std::hypot(arf-ar0,apf-ap0);std::cout<<"\nDecision helper:\n final 0 FC tilt delta="<<dfc<<" deg\n final 0 ACC tilt delta="<<dacc<<" deg\n worst FC-vs-ACC gravity angle="<<worst<<" deg\n";if(dacc<0.3&&dfc>0.8)std::cout<<" RESULT: physical gravity direction returned, but FC ATTITUDE tilt did not. Investigate FC estimator/source semantics rather than accelerometer calibration.\n";else if(dacc>0.8)std::cout<<" RESULT: accelerometer gravity direction also changed substantially. Check stand repeatability/real tilt before blaming FC ATTITUDE.\n";else std::cout<<" RESULT: mixed/weak separation; inspect per-phase FC-vs-ACC gravity angles.\n";
}
static void hud35(const Att35&a,double rel,const Eigen::Vector3d&acc,const Eigen::Vector3d&gyro,bool started,bool done,int ph,int stable,int collected){cv::Mat c(850,1300,CV_8UC3,cv::Scalar(15,15,15));cv::Scalar w(235,235,235),gr(80,220,80),ye(0,220,255);uiText(c,"JT-ZERO: FC ATTITUDE ПРОТИВ GRAVITY ACCEL v35",30,52,.68,w,2);if(!started){uiText(c,"УСТАНОВИТЕ СТЕНД В ИСХОДНЫЙ 0°",70,120,.62,ye,2);uiText(c,"SPACE — ЗАФИКСИРОВАТЬ НОЛЬ И НАЧАТЬ",70,175,.56,w,2);}else if(done){uiText(c,"ТЕСТ ЗАВЕРШЁН",70,120,.82,gr,3);uiText(c,"SPACE — ВЫХОД",70,175,.52,w,2);}else{char t[128];snprintf(t,sizeof(t),"ЭТАП %d/5: YAW К %+.0f°",ph+1,kTargets35[ph]);uiText(c,t,70,120,.65,ye,2);uiText(c,stable>=kStableSamples35?"СТОП! СТЕНД НЕ ДВИГАТЬ — ИДЁТ СБОР":"ПОПАДИТЕ В ЗЕЛЁНУЮ ЗОНУ И ОСТАНОВИТЕСЬ",70,175,.52,stable>=kStableSamples35?gr:w,2);}cv::Mat q=c(cv::Rect(50,230,1200,550));drawBar(q,"YAW",rel,-105,105,done?0:kTargets35[ph],kYawTol35,65);double ar=0,ap=0;if(acc.norm()>1)accelTilt35(acc,ar,ap);char t[256];snprintf(t,sizeof(t),"FC: R %+.2f°   P %+.2f°   YAW %+.2f°",a.roll,a.pitch,rel);uiText(q,t,20,140,.48,w,1);snprintf(t,sizeof(t),"ACC gravity: R %+.2f°   P %+.2f°",ar,ap);uiText(q,t,20,195,.48,gr,1);snprintf(t,sizeof(t),"|gyro| %.4f rad/s   |acc| %.4f m/s²",gyro.norm(),acc.norm());uiText(q,t,20,250,.44,w,1);snprintf(t,sizeof(t),"Стабилизация %d/%d   Собрано %d/%d",stable,kStableSamples35,collected,kCollectSamples35);uiText(q,t,20,305,.44,w,1);uiText(q,"Маршрут: 0 → +90 → 0 → -90 → 0",20,445,.45,w,1);cv::imshow(kWindow35,c);}
}

int main(int argc,char**argv){google::InitGoogleLogging(argv[0]);int fd=-1;uint8_t sys=0,comp=0;mavlink_status_t mst{};mavlink_message_t msg{};bool started=false,done=false;int ph=0,stable=0,collected=0;double ref=0;jtzero_v35::Att35 at;Eigen::Vector3d acc=Eigen::Vector3d::Zero(),gyro=Eigen::Vector3d::Zero();std::array<jtzero_v35::Stats35,jtzero_v35::kPhases35> stats;std::vector<jtzero_v35::Row35> rows;uint64_t last=0;try{fd=openSerial();std::cout<<"[MAV] waiting for HEARTBEAT...\n";int64_t dl=monotonicNs()+10000000000LL;while(monotonicNs()<dl&&!sys){pollfd p{fd,POLLIN,0};if(poll(&p,1,100)<=0)continue;uint8_t b[2048];ssize_t n=read(fd,b,sizeof(b));if(n<=0)continue;for(ssize_t i=0;i<n;i++)if(mavlink_parse_char(MAVLINK_COMM_0,b[i],&msg,&mst)&&msg.msgid==MAVLINK_MSG_ID_HEARTBEAT){sys=msg.sysid;comp=msg.compid;break;}}if(!sys)throw std::runtime_error("HEARTBEAT timeout");requestRate(fd,sys,comp,MAVLINK_MSG_ID_ATTITUDE,100);requestRate(fd,sys,comp,MAVLINK_MSG_ID_HIGHRES_IMU,200);cv::namedWindow(jtzero_v35::kWindow35);int64_t nh=0;while(true){pollfd p{fd,POLLIN,0};poll(&p,1,5);if(p.revents&POLLIN){uint8_t b[8192];ssize_t n=read(fd,b,sizeof(b));if(n>0)for(ssize_t i=0;i<n;i++)if(mavlink_parse_char(MAVLINK_COMM_0,b[i],&msg,&mst)){if(msg.msgid==MAVLINK_MSG_ID_ATTITUDE){mavlink_attitude_t a{};mavlink_msg_attitude_decode(&msg,&a);at.valid=true;at.roll=a.roll*180/kPi;at.pitch=a.pitch*180/kPi;at.yaw=a.yaw*180/kPi;at.R=jtzero_v10::fcRnedFlu(at.roll,at.pitch,at.yaw);}else if(msg.msgid==MAVLINK_MSG_ID_HIGHRES_IMU){mavlink_highres_imu_t h{};mavlink_msg_highres_imu_decode(&msg,&h);if(h.time_usec==last)continue;last=h.time_usec;acc={h.xacc,-h.yacc,-h.zacc};gyro={h.xgyro,-h.ygyro,-h.zgyro};if(started&&!done&&at.valid){double rel=jtzero_v35::normDeg35(at.yaw-ref);bool ok=std::abs(jtzero_v35::normDeg35(rel-jtzero_v35::kTargets35[ph]))<=jtzero_v35::kYawTol35&&gyro.norm()<=jtzero_v35::kGyroStill35&&std::abs(acc.norm()-9.81)<=jtzero_v35::kAccNormTol35;if(ok){if(stable<jtzero_v35::kStableSamples35)stable++;else{jtzero_v35::Row35 r;r.phase=ph;r.us=h.time_usec;r.rel_yaw=rel;r.fc_roll=at.roll;r.fc_pitch=at.pitch;r.fc_yaw=at.yaw;r.acc=acc;rows.push_back(r);stats[ph].add(r);if(++collected>=jtzero_v35::kCollectSamples35){std::cout<<"[STEP] "<<jtzero_v35::kNames35[ph]<<" collected.\n";stable=collected=0;if(++ph>=jtzero_v35::kPhases35){ph=4;done=true;std::cout<<"[TEST] completed.\n";}else std::cout<<"[NEXT] target "<<jtzero_v35::kTargets35[ph]<<" deg.\n";}}}else stable=0;}}}}if(monotonicNs()>=nh){double rel=started&&at.valid?jtzero_v35::normDeg35(at.yaw-ref):0;jtzero_v35::hud35(at,rel,acc,gyro,started,done,ph,stable,collected);nh=monotonicNs()+33333333LL;}int k=cv::waitKey(1)&255;if(k==27||k=='q'||k=='Q')break;if(k==' '&&!started&&at.valid){ref=at.yaw;started=true;std::cout<<"[ZERO] reference fixed.\n";}else if(k==' '&&done)break;}jtzero_v35::save35(rows);jtzero_v35::summary35(stats);std::cout<<"\nCSV: "<<jtzero_v35::kCsv35<<"\nOpen CSV:\n  code "<<jtzero_v35::kCsv35<<"\n";requestRate(fd,sys,comp,MAVLINK_MSG_ID_ATTITUDE,0);requestRate(fd,sys,comp,MAVLINK_MSG_ID_HIGHRES_IMU,0);close(fd);cv::destroyAllWindows();return 0;}catch(const std::exception&e){if(fd>=0)close(fd);cv::destroyAllWindows();std::cerr<<"[FATAL] "<<e.what()<<"\n";return 1;}}
